//! Kernel/userspace ABI types, generated by bindgen from `rk-bpf/include/rk_abi.h`
//! (see `build.rs`). Enums are constant modules, so a hostile value from the
//! kernel can never become an invalid Rust enum.

#![no_std]

#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all,
    clippy::pedantic
)]
mod bindings {
    include!(concat!(env!("OUT_DIR"), "/rk_abi.rs"));
}

pub use bindings::*;

/// Size of the fixed envelope that precedes every payload:
/// `rk_hdr` + `payload_len` + `_reserved`.
pub const RK_ENVELOPE_LEN: usize = core::mem::size_of::<rk_hdr>() + 8;

// Hand-written mirror of the `_Static_assert`s in rk_abi.h. bindgen also emits
// its own size/offset assertions; both run at compile time on every target.
const _: () = {
    use core::mem::{offset_of, size_of};

    assert!(size_of::<rk_hdr>() == 48);
    assert!(offset_of!(rk_hdr, ts_ns) == 0);
    assert!(offset_of!(rk_hdr, cgroup_id) == 8);
    assert!(offset_of!(rk_hdr, policy_gen) == 16);
    assert!(offset_of!(rk_hdr, pid) == 24);
    assert!(offset_of!(rk_hdr, tgid) == 28);
    assert!(offset_of!(rk_hdr, uid) == 32);
    assert!(offset_of!(rk_hdr, gid) == 36);
    assert!(offset_of!(rk_hdr, type_) == 40);
    assert!(offset_of!(rk_hdr, verdict) == 42);
    assert!(offset_of!(rk_hdr, abi) == 43);
    assert!(offset_of!(rk_hdr, rule_id) == 44);

    assert!(RK_ENVELOPE_LEN == 56);
    assert!(offset_of!(rk_scratch_msg, hdr) == 0);
    assert!(offset_of!(rk_scratch_msg, payload_len) == 48);
    assert!(offset_of!(rk_scratch_msg, _reserved) == 52);
    assert!(offset_of!(rk_scratch_msg, payload) == RK_ENVELOPE_LEN);
    assert!(size_of::<rk_scratch_msg>() == RK_ENVELOPE_LEN + RK_SCRATCH_PAYLOAD_MAX as usize);

    assert!(size_of::<rk_payload_exec>() == 24);
    assert!(offset_of!(rk_payload_exec, file_dev) == 0);
    assert!(offset_of!(rk_payload_exec, file_ino) == 8);
    assert!(offset_of!(rk_payload_exec, flags) == 16);
    assert!(offset_of!(rk_payload_exec, str_count) == 20);

    assert!(size_of::<rk_payload_file>() == 32);
    assert!(offset_of!(rk_payload_file, file_dev) == 0);
    assert!(offset_of!(rk_payload_file, file_ino) == 8);
    assert!(offset_of!(rk_payload_file, open_flags) == 16);
    assert!(offset_of!(rk_payload_file, mode) == 20);
    assert!(offset_of!(rk_payload_file, str_count) == 24);
    assert!(offset_of!(rk_payload_file, _pad2) == 28);

    assert!(size_of::<rk_payload_net>() == 40);
    assert!(offset_of!(rk_payload_net, saddr_v6) == 0);
    assert!(offset_of!(rk_payload_net, daddr_v6) == 16);
    assert!(offset_of!(rk_payload_net, sport) == 32);
    assert!(offset_of!(rk_payload_net, dport) == 34);
    assert!(offset_of!(rk_payload_net, family) == 36);
    assert!(offset_of!(rk_payload_net, protocol) == 38);
};

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn abi_constants_match_header() {
        assert_eq!(RK_ABI_VERSION, 1);
        assert_eq!(RK_SCRATCH_PAYLOAD_MAX, 2048);
        assert_eq!(rk_event_type::RK_EV_SENDMSG, 9);
        assert_eq!(rk_verdict::RK_VERDICT_AUDIT_WOULD_DENY, 2);
        assert_eq!(rk_counter::RK_CNT_MAX, 2);
    }

    #[test]
    fn abi_structs_are_pod() {
        // Compiles only because every ABI struct derives Pod (no padding).
        let hdr: rk_hdr = bytemuck::Zeroable::zeroed();
        assert_eq!(bytemuck::bytes_of(&hdr).len(), 48);
        let net: rk_payload_net = bytemuck::Zeroable::zeroed();
        assert_eq!(bytemuck::bytes_of(&net).len(), 40);
    }
}
